<script setup lang="ts">
import { canTransitionAppointment } from "~/utils/appointmentTransitions"
const route = useRoute();
const auth = useAdminApi();
const {api,page,lastPage,errorText,money,dateTime,localDate,query} = useBooking();
const section = computed(() => String(route.params.section || 'dashboard'));
const links = [ ['dashboard','داشبورد'],['appointments','نوبت‌ها'],['calendar','تقویم'],['clients','مراجعان'],['services','خدمات'],['schedule','برنامه مشاور'],['finance','مالی'],['refunds','بازپرداخت'],['notifications','اعلان‌ها'] ];
const loading=ref(false), busy=ref(false), error=ref(''), success=ref('');
const rows=ref<any[]>([]), extra=ref<any[]>([]), bookings=ref<any[]>([]), slots=ref<any[]>([]), counselors=ref<any[]>([]), services=ref<any[]>([]), clients=ref<any[]>([]), rooms=ref<any[]>([]);
const totalPages=ref(1), currentPage=ref(1), selected=ref<any>(null), dialog=ref('');
const filters=reactive({date:'',counselor_id:null as number|null,service_id:null as number|null,status:'',from:'',to:'',provider:'',payment_method:''});
const calDate=ref(localDate()), calView=ref('day'), calService=ref<number|null>(null), calRoom=ref<number|null>(null), calStatus=ref('');
const clientQ=ref(''), appointmentQ=ref(''), selectedClient=ref<any>(null);
const bookingForm=reactive({user_id:null as number|null,counselor_id:null as number|null,service_id:null as number|null,room_id:null as number|null,starts_at:'',mode:'in_person',payment_option:'deposit',promo_code:''});
const paymentForm=reactive({amount_irr:0,payment_method:'cash',reference:''});
const noteForm=reactive({body:'',visible_to_client:false});
const notes=ref<any[]>([]), payments=ref<any[]>([]), refunds=ref<any[]>([]), report=ref<any>({}), financeSummary=ref<any>({}), reconciliation=ref<any>({});
const serviceForm=reactive({id:null as number|null,title:'',duration_minutes:60,price_irr:0,deposit_irr:0,is_active:true});
const assignment=reactive({service_id:null as number|null,price_irr:null as number|null,commission_type:'percentage',commission_value:0});
const shift=reactive({weekday:0,starts_at:'09:00',ends_at:'12:00'});
const off=reactive({starts_at:'',ends_at:'',reason:''});
const clientForm=reactive({name:'',email:'',phone:''});
const settlement=reactive({counselor_id:null as number|null,amount_irr:0,reference:'',note:''});
const refundForm=reactive({amount_irr:0,reason:''});
const partialRefundOpen=ref(false);
const payable=ref<any>(null);
const statusNames:any={held:'در انتظار پرداخت',confirmed:'تأیید شده',completed:'برگزار شده',cancelled:'لغو شده',expired:'منقضی',requested:'درخواست شده',approved:'تأیید شده',rejected:'رد شده',refunded:'بازپرداخت شده',pending:'در انتظار',verified:'پرداخت شده',failed:'ناموفق',processing:'در حال پردازش',sent:'ارسال شده',created:'ایجاد شده'};
const weekdayNames=['یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه','شنبه'];
const label=(value:string)=>statusNames[value]||value||'—';
const statusColor=(value:string)=>({confirmed:'success',verified:'success',completed:'primary',held:'warning',requested:'info',processing:'info',approved:'success',refunded:'secondary',cancelled:'error',rejected:'error',failed:'error',expired:'secondary'} as Record<string,string>)[value]||'default';
const q=(values:any)=>{const s=query(values);return s?`?${s}`:''};
const wrap=async(fn:()=>Promise<void>)=>{busy.value=true;error.value='';success.value='';try{await fn();success.value='عملیات ثبت شد.';}catch(e:any){error.value=errorText(e);}finally{busy.value=false;}};
async function loadCommon(){
 try {
  if(auth.can('counselors.manage')) {
   const c=await auth.request<any>('/admin/counselors?page=1');
   const rest=await Promise.all(Array.from({length:lastPage(c)-1},(_,i)=>auth.request<any>(`/admin/counselors?page=${i+2}`)));
   counselors.value=[c,...rest].flatMap(page);
  } else if(auth.can('appointments.manage')) {
   // Reception only needs public counselor names and ids; the admin directory requires a separate permission.
   const c=await auth.request<any>('/counselors?page=1');
   const pages=lastPage(c);
   const rest=await Promise.all(Array.from({length:pages-1},(_,i)=>auth.request<any>(`/counselors?page=${i+2}`)));
   counselors.value=[c,...rest].flatMap(page);
  }
  if(auth.can('appointments.manage')) services.value=await allPages('/services');
  if(auth.can('appointments.manage')) { const roomResult=await api<any>(`/rooms?date=${calDate.value}`); rooms.value=roomResult.data||[]; }
 }
 catch(e:any){error.value=errorText(e);}
}
async function load(){
 loading.value=true;error.value='';
 try{
  if(section.value==='dashboard'){
   const [dashboard,r]=await Promise.all([api<any>('/reception/dashboard'),auth.can('finance.view')?api<any>('/refunds'):Promise.resolve(null)]);
   const metrics=dashboard.data||{};rows.value=metrics.today||[];bookings.value=metrics.upcoming||[];refunds.value=r?page(r):[];
   totalPages.value=1;
   if(auth.can('finance.view')){const reportResponse=await api<any>('/reports');report.value=reportResponse.data;}
  }else if(section.value==='appointments'){
   const r=await api<any>(`/reservations${q({page:currentPage.value,date:filters.date,counselor_id:filters.counselor_id,status:filters.status,q:appointmentQ.value.trim()})}`);rows.value=page(r);totalPages.value=lastPage(r);
  }else if(section.value==='calendar')await loadCalendar();
  else if(section.value==='services'){const r=await api<any>(`/services?page=${currentPage.value}`);rows.value=page(r);totalPages.value=lastPage(r);services.value=rows.value;}
  else if(section.value==='schedule')await loadSchedule();
  else if(section.value==='finance'){
   const args=q({from:filters.from,to:filters.to,counselor_id:filters.counselor_id,service_id:filters.service_id,provider:filters.provider,payment_method:filters.payment_method,booking_status:filters.status,group:'day'});
   const [r,p,s,x,f]=await Promise.all([api<any>(`/reports${args}`),api<any>(`/payments?page=${currentPage.value}`),api<any>(`/settlements${q({counselor_id:filters.counselor_id})}`),api<any>(`/reconciliation${q({counselor_id:filters.counselor_id})}`),api<any>(`/finance/dashboard${q({from:filters.from,to:filters.to,counselor_id:filters.counselor_id,service_id:filters.service_id})}`)]);
   report.value=r.data;rows.value=page(p);totalPages.value=lastPage(p);extra.value=page(s);reconciliation.value=x.data;financeSummary.value=f.data;
   payable.value=filters.counselor_id?(await api<any>(`/counselors/${filters.counselor_id}/payable`)).data:null;
  }else if(section.value==='refunds'){const r=await api<any>(`/refunds?page=${currentPage.value}`);rows.value=page(r);totalPages.value=lastPage(r);}
  else if(section.value==='notifications'){const r=await api<any>(`/notifications?page=${currentPage.value}`);rows.value=page(r);totalPages.value=lastPage(r);}
  else if(section.value==='clients'){rows.value=[];if(clientQ.value.trim().length>=2)rows.value=page(await api<any>(`/clients${q({q:clientQ.value.trim()})}`));}
 }catch(e:any){error.value=errorText(e);}finally{loading.value=false;}
}
async function loadCalendar(){
 if(calView.value==='month'){
  const result=await api<any>(`/calendar${q({date:calDate.value,view:'month',counselor_id:filters.counselor_id,service_id:calService.value,room_id:calRoom.value,status:calStatus.value})}`);
  bookings.value=result.data||[];slots.value=[];return;
 }
 const dates=calView.value==='week'?Array.from({length:7},(_,i)=>{const d=new Date(`${calDate.value}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+i);return d.toISOString().slice(0,10);}):[calDate.value];
 const results=await Promise.all(dates.map(date=>api<any>(`/calendar${q({date,view:'day',counselor_id:filters.counselor_id,service_id:calService.value,room_id:calRoom.value,status:calStatus.value})}`)));
 bookings.value=results.flatMap(r=>r.data||[]); slots.value=results.flatMap(r=>r.slots||[]);
}
async function loadSchedule(){
 if(!filters.counselor_id){rows.value=[];extra.value=[];return;}
 const id=filters.counselor_id;const [shifts,offs]=await Promise.all([api<any>(`/counselors/${id}/shifts`),api<any>(`/counselors/${id}/time-off`)]);
 rows.value=shifts.data;extra.value=page(offs);
}
async function findClients(){if(clientQ.value.trim().length<2){clients.value=[];return;}try{clients.value=page(await api<any>(`/clients${q({q:clientQ.value.trim()})}`));}catch(e:any){error.value=errorText(e);}}
async function allPages(path:string){const first=await api<any>(`${path}${path.includes('?')?'&':'?'}page=1`);const count=lastPage(first);if(count<=1)return page(first);const rest=await Promise.all(Array.from({length:count-1},(_,i)=>api<any>(`${path}${path.includes('?')?'&':'?'}page=${i+2}`)));return [first,...rest].flatMap(page);}
async function clientHistory(client:any){selectedClient.value=client;dialog.value='client';await wrap(async()=>{bookings.value=await allPages(`/reservations${q({client_id:client.id})}`);});}
async function detail(row:any){selected.value=row;bookingForm.room_id=row.room_id||null;dialog.value='detail';notes.value=[];payments.value=[];refunds.value=[];try{
 const result=await api<any>(`/reservations/${row.id}`);
 selected.value=result.data||row;
 if(auth.can('finance.view')){payments.value=result.payments||[];refunds.value=result.refunds||[];}
 if(auth.can('notes.manage'))notes.value=(await api<any>(`/reservations/${row.id}/notes`)).data;
 }catch(e:any){error.value=errorText(e);}}
async function openNew(start=''){bookingForm.user_id=null;bookingForm.counselor_id=filters.counselor_id;bookingForm.service_id=calService.value;bookingForm.room_id=calRoom.value;bookingForm.promo_code='';bookingForm.starts_at=start;dialog.value='new';clients.value=[];clientQ.value='';}
async function fetchSlots(){slots.value=[];bookingForm.starts_at='';if(!bookingForm.counselor_id||!bookingForm.service_id||!calDate.value)return;try{const r=await api<any>(`/calendar${q({date:calDate.value,counselor_id:bookingForm.counselor_id,service_id:bookingForm.service_id})}`);slots.value=r.slots||[];}catch(e:any){error.value=errorText(e);}}
async function createBooking(){await wrap(async()=>{if(!bookingForm.user_id||!bookingForm.starts_at)throw {data:{message:'مراجع و زمان آزاد را انتخاب کنید.'}};if(bookingForm.room_id&&bookingForm.mode!=='in_person')throw {data:{message:'تخصیص اتاق فقط برای جلسهٔ حضوری مجاز است.'}};await api('/reservations',{method:'POST',body:bookingForm});dialog.value='';await load();});}
async function reschedule(start:string){await wrap(async()=>{await api(`/reservations/${selected.value.id}/reschedule`,{method:'PATCH',body:{starts_at:start}});dialog.value='';await load();});}
async function cancelBooking(){const reason=prompt('دلیل لغو نوبت (فقط نوبت بدون پرداخت)');if(!reason)return;await wrap(async()=>{await api(`/reservations/${selected.value.id}/cancel`,{method:'POST',body:{reason}});dialog.value='';await load();});}
async function setSessionStatus(status:'in_progress'|'completed'|'no_show'){
 if(!selected.value)return;
 const allowed=canTransitionAppointment(selected.value.status,status);
 if(!allowed)return;
 const message=status==='in_progress'?'شروع این جلسه ثبت شود؟':status==='completed'?'برگزاری این جلسه ثبت شود؟':'عدم حضور مراجع ثبت شود؟';
 if(!confirm(message))return;
 await wrap(async()=>{await api(`/reservations/${selected.value.id}/status`,{method:'PATCH',body:{status}});await detail(selected.value);await load();});
}
async function checkInSelected(){if(!selected.value||selected.value.status!=='confirmed')return;await wrap(async()=>{await api(`/reservations/${selected.value.id}/check-in`,{method:'POST'});await detail(selected.value);await load();});}
async function assignSelectedRoom(){if(!selected.value)return;await wrap(async()=>{await api(`/reservations/${selected.value.id}/room`,{method:'PATCH',body:{room_id:bookingForm.room_id}});await detail(selected.value);await load();});}
async function requestPartialRefund(){if(!selected.value||busy.value)return;await wrap(async()=>{if(refundForm.amount_irr<=0||!refundForm.reason.trim())throw {data:{message:'مبلغ و دلیل بازپرداخت را وارد کنید.'}};await api(`/reservations/${selected.value.id}/refunds`,{method:'POST',body:{...refundForm}});partialRefundOpen.value=false;Object.assign(refundForm,{amount_irr:0,reason:''});await detail(selected.value);await load();});}
async function recordPayment(){await wrap(async()=>{if(!paymentForm.reference.trim())throw {data:{message:'شماره رسید یا مرجع لازم است.'}};await api(`/reservations/${selected.value.id}/payments/in-person`,{method:'POST',body:{...paymentForm,idempotency_key:crypto.randomUUID()}});dialog.value='';await load();});}
async function addNote(){await wrap(async()=>{await api(`/reservations/${selected.value.id}/notes`,{method:'POST',body:noteForm});noteForm.body='';notes.value=(await api<any>(`/reservations/${selected.value.id}/notes`)).data;});}
async function saveService(){await wrap(async()=>{const {id,...body}=serviceForm;await api(`/services${id?'/'+id:''}`,{method:id?'PATCH':'POST',body});dialog.value='';await load();});}
async function createClient(){await wrap(async()=>{const r=await api<any>('/clients',{method:'POST',body:clientForm});bookingForm.user_id=r.data.id;clients.value=[r.data];dialog.value='new';await load();});}
async function assignService(){await wrap(async()=>{await api(`/counselors/${filters.counselor_id}/services`,{method:'PUT',body:assignment});});}
async function addShift(){await wrap(async()=>{if(shift.ends_at<=shift.starts_at||rows.value.some((s:any)=>s.is_active&&Number(s.weekday)===Number(shift.weekday)&&s.starts_at<shift.ends_at&&s.ends_at>shift.starts_at))throw {data:{message:'ساعت شیفت نامعتبر است یا با شیفت فعال دیگری تداخل دارد.'}};await api(`/counselors/${filters.counselor_id}/shifts`,{method:'POST',body:shift});await loadSchedule();});}
async function toggleShift(row:any){await wrap(async()=>{await api(`/shifts/${row.id}`,{method:'PATCH',body:{is_active:!row.is_active}});await loadSchedule();});}
async function addOff(){await wrap(async()=>{const offset=(v:string)=>`${v}:00+03:30`;await api(`/counselors/${filters.counselor_id}/time-off`,{method:'POST',body:{starts_at:offset(off.starts_at),ends_at:offset(off.ends_at),reason:off.reason}});await loadSchedule();});}
async function removeOff(row:any){if(!confirm('این بازه حذف شود؟'))return;await wrap(async()=>{await api(`/time-off/${row.id}`,{method:'DELETE'});await loadSchedule();});}
async function decideRefund(row:any,decision:string){if(!confirm(decision==='approved'?'درخواست لغو تأیید شود؟':'درخواست رد شود؟'))return;await wrap(async()=>{await api(`/refunds/${row.id}`,{method:'PATCH',body:{decision}});await load();});}
async function transferRefund(row:any){const reference=prompt('مرجع انتقال انجام شده را وارد کنید');if(!reference)return;await wrap(async()=>{await api(`/refunds/${row.id}/record-transfer`,{method:'POST',body:{reference}});await load();});}
async function settle(){await wrap(async()=>{await api('/settlements',{method:'POST',body:settlement});dialog.value='';await load();});}
async function exportReport(){try{error.value='';const config=useRuntimeConfig();const params=query({from:filters.from,to:filters.to,counselor_id:filters.counselor_id,service_id:filters.service_id,booking_status:filters.status});const response=await fetch(`${config.public.apiBase}/admin/booking/reports/export?${params}`,{headers:{Authorization:`Bearer ${auth.token.value}`,Accept:'text/csv'}});if(!response.ok)throw {status:response.status,data:{message:'خروجی گزارش دریافت نشد.'}};const url=URL.createObjectURL(await response.blob()),anchor=document.createElement('a');anchor.href=url;anchor.download='booking-report.csv';anchor.click();URL.revokeObjectURL(url);}catch(e:any){error.value=errorText(e);}}
const counselorName=(id:any)=>counselors.value.find((c:any)=>c.id===id)?.name||`#${id}`;
const serviceName=(id:any)=>services.value.find((s:any)=>s.id===id)?.title||`#${id}`;
const visibleRows=computed(()=>rows.value);
const pendingRefunds=computed(()=>refunds.value.filter((r:any)=>r.status==='requested'));
const availableSlots=computed(()=>slots.value.filter((s:any)=>s.available));
const dashboardCards=computed(()=>[
 {title:'نوبت‌های امروز · صفحه جاری',value:rows.value.length,icon:'mdi-calendar-today',tone:'indigo'},
 {title:'در انتظار پرداخت · صفحه جاری',value:rows.value.filter((x:any)=>x.status==='held').length,icon:'mdi-timer-sand',tone:'sand'},
 {title:'درخواست لغو · صفحه جاری',value:pendingRefunds.value.length,icon:'mdi-calendar-remove-outline',tone:'rose',finance:true},
 {title:'مجموع دریافت گزارش‌شده',value:money(report.value?.collected_irr),icon:'mdi-cash-multiple',tone:'sage',finance:true},
].filter(card=>!card.finance||auth.can('finance.view')));
const calendarDates=computed(()=>{if(calView.value==='month'){const date=new Date(`${calDate.value}T12:00:00Z`),days=new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth()+1,0)).getUTCDate();return Array.from({length:days},(_,i)=>new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth(),i+1)).toISOString().slice(0,10));}return calView.value==='week'?Array.from({length:7},(_,i)=>{const d=new Date(`${calDate.value}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+i);return d.toISOString().slice(0,10);}):[calDate.value];});
const bookingsOn=(date:string)=>bookings.value.filter((b:any)=>localDate(new Date(b.starts_at))===date);
const slotsOn=(date:string)=>availableSlots.value.filter((s:any)=>localDate(new Date(s.starts_at))===date);
const calendarLabel=(date:string)=>new Intl.DateTimeFormat('fa-IR-u-ca-persian',{timeZone:'Asia/Tehran',weekday:'long',day:'numeric',month:'short'}).format(new Date(`${date}T12:00:00+03:30`));
function editService(row:any){Object.assign(serviceForm,row);dialog.value='service';}
function newService(){Object.assign(serviceForm,{id:null,title:'',duration_minutes:60,price_irr:0,deposit_irr:0,is_active:true});dialog.value='service';}
async function previewReschedule(row:any){selected.value=row;bookingForm.counselor_id=row.counselor_id;bookingForm.service_id=row.booking_service_id;calDate.value=localDate(new Date(row.starts_at));await fetchSlots();dialog.value='reschedule';}
watch(()=>route.fullPath,()=>{currentPage.value=1;load();});watch(currentPage,load);
let appointmentSearchTimer:ReturnType<typeof setTimeout>|undefined;
watch(appointmentQ,()=>{if(section.value!=='appointments')return;clearTimeout(appointmentSearchTimer);appointmentSearchTimer=setTimeout(()=>{currentPage.value=1;load();},300);});
onBeforeUnmount(()=>clearTimeout(appointmentSearchTimer));
onMounted(async()=>{await loadCommon();await load();});
</script>

<template>
  <div dir="rtl" class="booking-workspace">
    <div v-if="section==='dashboard'" class="booking-hero d-flex flex-wrap align-center justify-space-between ga-4 mb-6">
      <div><div class="admin-eyebrow">پذیرش و هماهنگی جلسات</div><h2 class="mb-1">داشبورد رزرو</h2><div class="text-medium-emphasis">نمای روزانه نوبت‌ها، ظرفیت و امور مالی مرکز</div></div>
      <div class="d-flex ga-2"><v-btn v-if="auth.can('appointments.manage')" color="primary" prepend-icon="mdi-plus" @click="openNew()">نوبت جدید</v-btn><v-btn variant="outlined" prepend-icon="mdi-refresh" :loading="loading" @click="load">به‌روزرسانی</v-btn></div>
    </div>
    <div v-else class="d-flex flex-wrap align-center justify-space-between ga-3 mb-5">
      <div><h2 class="mb-1">{{ links.find(x => x[0] === section)?.[1] || 'داشبورد رزرو' }}</h2><div class="text-medium-emphasis">مدیریت نوبت، پذیرش و امور مالی</div></div>
      <div class="d-flex ga-2"><v-btn v-if="auth.can('appointments.manage')" color="primary" @click="openNew()">نوبت جدید</v-btn><v-btn variant="tonal" :loading="loading" @click="load">تازه‌سازی</v-btn></div>
    </div>
    <v-alert v-if="error" type="error" closable class="mb-4" @click:close="error=''">{{ error }}</v-alert>
    <v-alert v-if="success" type="success" closable class="mb-4" @click:close="success=''">{{ success }}</v-alert>
    <v-progress-linear v-if="loading" indeterminate color="primary" class="mb-3" />

    <template v-if="section==='dashboard'">
      <v-row class="mb-2">
        <v-col v-for="card in dashboardCards" :key="card.title" cols="12" sm="6" lg="3"><v-card class="booking-kpi" :class="`tone-${card.tone}`"><div class="d-flex justify-space-between align-start"><div><div class="booking-kpi__label">{{ card.title }}</div><div class="booking-kpi__value">{{ card.value }}</div></div><v-icon :icon="card.icon" size="22" /></div></v-card></v-col>
      </v-row>
      <v-row class="mb-1"><v-col cols="12" md="5"><v-text-field v-if="!counselors.length" v-model.number="filters.counselor_id" type="number" label="شناسه مشاور" hide-details /><v-select v-else v-model="filters.counselor_id" :items="counselors" item-title="name" item-value="id" label="فیلتر مشاور" clearable hide-details @update:model-value="load" /></v-col><v-col cols="12" md="7" class="d-flex flex-wrap ga-2"><v-btn v-for="link in links.slice(1,7)" :key="link[0]" :to="`/booking/${link[0]}`" variant="tonal" size="small">{{ link[1] }}</v-btn></v-col></v-row>
      <v-row><v-col cols="12" :lg="auth.can('finance.view') ? 7 : 12"><v-card class="pa-4 h-100 data-card"><div class="d-flex align-center justify-space-between mb-2"><div><h3>نوبت‌های آینده</h3><div class="text-caption text-medium-emphasis">{{ bookings.length }} مورد در صفحه جاری</div></div><v-btn variant="text" size="small" to="/booking/appointments">همه نوبت‌ها</v-btn></div><v-list v-if="bookings.length" class="bg-transparent"><v-list-item v-for="b in bookings.slice(0,6)" :key="b.id" :title="`${dateTime(b.starts_at)} · ${counselorName(b.counselor_id)}`" :subtitle="`${serviceName(b.booking_service_id)} · ${label(b.status)}`" prepend-icon="mdi-calendar-check-outline" @click="detail(b)" /></v-list><div v-else class="pa-5 text-center text-medium-emphasis">نوبت آینده‌ای در صفحه جاری یافت نشد.</div></v-card></v-col><v-col v-if="auth.can('finance.view')" cols="12" lg="5"><v-card class="pa-4 h-100 data-card"><div class="d-flex align-center justify-space-between mb-2"><div><h3>درخواست‌های بازپرداخت</h3><div class="text-caption text-medium-emphasis">موارد دریافت‌شده در صفحه جاری</div></div><v-btn variant="text" size="small" to="/booking/refunds">مشاهده</v-btn></div><v-list v-if="pendingRefunds.length" class="bg-transparent"><v-list-item v-for="r in pendingRefunds.slice(0,5)" :key="r.id" :title="`درخواست نوبت #${r.booking_id}`" :subtitle="money(r.refund_amount_irr)" prepend-icon="mdi-cash-refund" /></v-list><div v-else class="pa-5 text-center text-medium-emphasis">درخواست بازی در این صفحه نیست.</div></v-card></v-col></v-row>
