      <v-card class="data-card"><v-table><thead><tr><th>شناسه</th><th>زمان</th><th>مراجع</th><th>مشاور</th><th>خدمت</th><th>وضعیت</th><th>مانده</th><th></th></tr></thead><tbody><tr v-for="b in visibleRows" :key="b.id"><td>{{ b.id }}</td><td>{{ dateTime(b.starts_at) }}</td><td>{{ b.user_id }}</td><td>{{ counselorName(b.counselor_id) }}</td><td>{{ serviceName(b.booking_service_id) }}</td><td><v-chip size="small" :color="statusColor(b.status)" variant="tonal">{{ label(b.status) }}</v-chip></td><td>{{ money(b.remaining_irr) }}</td><td><v-btn size="small" variant="text" @click="detail(b)">جزئیات</v-btn></td></tr></tbody></v-table><div v-if="!visibleRows.length&&!loading" class="pa-6 text-center text-medium-emphasis">نوبتی یافت نشد.</div></v-card>
