    <template v-if="section==='calendar'">
      <v-row><v-col cols="12" md="3"><v-text-field v-model="calDate" type="date" label="تاریخ آغاز" /></v-col><v-col cols="12" md="3"><v-select v-model="calView" :items="[{title:'روزانه',value:'day'},{title:'هفتگی',value:'week'},{title:'ماهانه',value:'month'}]" label="نمایش" /></v-col><v-col cols="12" md="3"><v-text-field v-if="!counselors.length" v-model.number="filters.counselor_id" type="number" label="شناسه مشاور" /><v-select v-else v-model="filters.counselor_id" :items="counselors" item-title="name" item-value="id" label="مشاور" clearable /></v-col><v-col cols="12" md="3"><v-select v-model="calService" :items="services" item-title="title" item-value="id" label="خدمت برای ظرفیت آزاد" clearable /></v-col><v-col cols="12" md="3"><v-select v-model="calRoom" :items="rooms" item-title="name" item-value="id" label="اتاق" clearable /></v-col><v-col cols="12" md="3"><v-select v-model="calStatus" :items="['held','confirmed','checked_in','in_progress','completed','cancelled','expired','no_show']" :item-title="label" label="وضعیت نوبت" clearable /></v-col></v-row>
      <v-btn variant="tonal" class="mb-4" @click="load">نمایش تقویم</v-btn>
      <v-alert v-if="!filters.counselor_id||!calService" type="info" class="mb-4">برای دیدن ظرفیت‌های آزاد، مشاور و خدمت را انتخاب کنید.</v-alert>
      <template v-if="calView==='week'"><div class="calendar-week" aria-label="نمای هفتگی تقویم"><v-card v-for="date in calendarDates" :key="date" class="calendar-day pa-3"><div class="calendar-day__heading">{{ calendarLabel(date) }}</div><div class="calendar-day__count">{{ bookingsOn(date).length }} نوبت · {{ slotsOn(date).length }} ظرفیت آزاد</div><button v-for="b in bookingsOn(date)" :key="b.id" class="calendar-event" :class="`event-${b.status}`" type="button" @click="detail(b)"><strong>نوبت #{{ b.id }} · {{ dateTime(b.starts_at).split('،').pop() }}</strong><span>{{ counselorName(b.counselor_id) }}</span><small>{{ label(b.status) }}</small></button><button v-for="slot in slotsOn(date).slice(0,5)" :key="slot.starts_at" class="calendar-slot" type="button" @click="openNew(slot.starts_at)">{{ dateTime(slot.starts_at).split('،').pop() }} · آزاد</button><div v-if="!bookingsOn(date).length&&!slotsOn(date).length" class="calendar-empty">بدون مورد ثبت‌شده</div></v-card></div></template><template v-else-if="calView==='month'"><div class="calendar-week calendar-month" aria-label="نمای ماهانه تقویم"><v-card v-for="date in calendarDates" :key="date" class="calendar-day pa-2"><div class="calendar-day__heading">{{ calendarLabel(date) }}</div><button v-for="b in bookingsOn(date)" :key="b.id" class="calendar-event" :class="`event-${b.status}`" type="button" @click="detail(b)"><strong>#{{ b.id }} · {{ dateTime(b.starts_at).split('،').pop() }}</strong><span>{{ b.counselor_name || counselorName(b.counselor_id) }}</span></button><div v-if="!bookingsOn(date).length" class="calendar-empty">بدون نوبت</div></v-card></div></template><v-row v-else><v-col cols="12" md="6"><v-card class="pa-4"><h3>نوبت‌های ثبت شده</h3><v-list v-if="bookings.length" class="bg-transparent"><v-list-item v-for="b in bookings" :key="b.id" :title="`نوبت #${b.id} · ${dateTime(b.starts_at)} · ${counselorName(b.counselor_id)}`" :subtitle="`${label(b.status)} · مراجع ${b.user_id}`" prepend-icon="mdi-calendar-check-outline" @click="detail(b)" /></v-list><div v-else class="pa-4 text-medium-emphasis">نوبتی ثبت نشده است.</div></v-card></v-col><v-col cols="12" md="6"><v-card class="pa-4"><h3>ظرفیت‌های آزاد</h3><div class="d-flex flex-wrap ga-2 mt-3"><v-btn v-for="slot in availableSlots" :key="slot.starts_at" size="small" variant="tonal" @click="openNew(slot.starts_at)">{{ dateTime(slot.starts_at) }}</v-btn></div><div v-if="!availableSlots.length" class="pa-4 text-medium-emphasis">ظرفیت آزادی یافت نشد؛ روزهای تعطیل و مرخصی نیز در این نتیجه لحاظ می‌شوند.</div></v-card></v-col></v-row>
