    <template v-if="section==='clients'"><v-row><v-col cols="12" md="6"><v-text-field v-model="clientQ" label="نام یا شماره تماس (حداقل دو نویسه)" @keyup.enter="load" /></v-col><v-col cols="12" md="3"><v-btn class="mt-2" @click="load">جست‌وجو</v-btn></v-col><v-col cols="12" md="3"><v-btn class="mt-2" color="primary" @click="dialog='newClient'">مراجع جدید</v-btn></v-col></v-row><v-card><v-list v-if="rows.length"><v-list-item v-for="c in rows" :key="c.id" :title="c.name" :subtitle="`${c.phone||''} · ${c.email||''}`"><template #append><v-btn size="small" @click="clientHistory(c)">سوابق</v-btn></template></v-list-item></v-list><div v-else class="pa-6 text-medium-emphasis">برای یافتن مراجع جست‌وجو کنید.</div></v-card></template>

    <template v-if="section==='services'"><v-btn color="primary" class="mb-4" @click="newService">خدمت جدید</v-btn><v-card><v-table><thead><tr><th>خدمت</th><th>مدت</th><th>قیمت</th><th>بیعانه</th><th>وضعیت</th><th></th></tr></thead><tbody><tr v-for="s in rows" :key="s.id"><td>{{ s.title }}</td><td>{{ s.duration_minutes }} دقیقه</td><td>{{ money(s.price_irr) }}</td><td>{{ money(s.deposit_irr) }}</td><td>{{ s.is_active?'فعال':'غیرفعال' }}</td><td><v-btn size="small" @click="editService(s)">ویرایش</v-btn></td></tr></tbody></v-table><div v-if="!rows.length&&!loading" class="pa-6 text-medium-emphasis">خدمتی یافت نشد.</div></v-card></template>

