      <v-row v-if="filters.counselor_id"><v-col cols="12" lg="6"><v-card class="pa-4"><h3>شیفت‌های هفتگی</h3><v-row class="mt-2"><v-col cols="12" sm="4"><v-select v-model="shift.weekday" :items="weekdayNames.map((title,value)=>({title,value}))" label="روز" /></v-col><v-col cols="6" sm="3"><v-text-field v-model="shift.starts_at" type="time" label="شروع" /></v-col><v-col cols="6" sm="3"><v-text-field v-model="shift.ends_at" type="time" label="پایان" /></v-col><v-col cols="12" sm="2"><v-btn :loading="busy" @click="addShift">افزودن</v-btn></v-col></v-row><v-list><v-list-item v-for="s in rows" :key="s.id" :title="`${weekdayNames[s.weekday]} · ${s.starts_at} تا ${s.ends_at}`" :subtitle="s.is_active?'فعال':'غیرفعال'"><template #append><v-btn size="small" :disabled="busy" @click="toggleShift(s)">{{ s.is_active?'غیرفعال کردن':'فعال کردن' }}</v-btn></template></v-list-item></v-list></v-card></v-col>
      <v-col cols="12" lg="6"><v-card class="pa-4"><h3>مرخصی و عدم حضور</h3><v-text-field v-model="off.starts_at" type="datetime-local" label="شروع (تهران)" class="mt-3" /><v-text-field v-model="off.ends_at" type="datetime-local" label="پایان (تهران)" /><v-text-field v-model="off.reason" label="دلیل" /><v-btn :loading="busy" @click="addOff">ثبت عدم حضور</v-btn><v-list><v-list-item v-for="o in extra" :key="o.id" :title="`${dateTime(o.starts_at)} تا ${dateTime(o.ends_at)}`" :subtitle="o.reason"><template #append><v-btn size="small" color="error" :disabled="busy" @click="removeOff(o)">حذف</v-btn></template></v-list-item></v-list></v-card></v-col></v-row>
      <v-card v-if="filters.counselor_id" class="pa-4 mt-4"><h3 class="mb-3">قیمت و کمیسیون خدمت مشاور</h3><v-row><v-col cols="12" md="3"><v-select v-model="assignment.service_id" :items="services" item-title="title" item-value="id" label="خدمت" /></v-col><v-col cols="12" md="3"><v-text-field v-model.number="assignment.price_irr" type="number" label="قیمت ویژه (ریال، اختیاری)" /></v-col><v-col cols="12" md="3"><v-select v-model="assignment.commission_type" :items="[{title:'درصدی',value:'percentage'},{title:'مبلغ ثابت',value:'fixed'}]" label="نوع کمیسیون" /></v-col><v-col cols="12" md="3"><v-text-field v-model.number="assignment.commission_value" type="number" label="مقدار کمیسیون" /></v-col></v-row><v-btn :loading="busy" :disabled="!assignment.service_id" @click="assignService">ثبت تخصیص</v-btn></v-card></template>

    <template v-if="section==='finance'"><v-row><v-col cols="12" md="3"><v-text-field v-model="filters.from" type="date" label="از تاریخ" /></v-col><v-col cols="12" md="3"><v-text-field v-model="filters.to" type="date" label="تا تاریخ" /></v-col><v-col cols="12" md="3"><v-text-field v-if="!counselors.length" v-model.number="filters.counselor_id" type="number" label="شناسه مشاور" /><v-select v-else v-model="filters.counselor_id" :items="counselors" item-title="name" item-value="id" label="مشاور" clearable /></v-col><v-col cols="12" md="3"><v-btn class="mt-2" @click="load">گزارش</v-btn><v-btn class="mt-2" variant="tonal" :disabled="!auth.can('finance.view')" @click="exportReport">دریافت CSV گزارش</v-btn></v-col></v-row><v-row><v-col cols="12" md="3"><v-select v-model="filters.status" :items="['held','confirmed','checked_in','in_progress','completed','cancelled','expired','no_show']" :item-title="label" label="وضعیت نوبت در گزارش" clearable /></v-col><v-col cols="12" md="3"><v-select v-model="filters.service_id" :items="services" item-title="title" item-value="id" label="خدمت" clearable /></v-col><v-col cols="12" md="4"><v-select v-model="filters.provider" :items="['fake_bank','in_person','mock','zarinpal','snappay']" label="ارائه‌دهنده پرداخت در گزارش" clearable /></v-col><v-col cols="12" md="4"><v-select v-model="filters.payment_method" :items="['cash','pos']" label="روش حضوری در گزارش" clearable /></v-col></v-row><v-row><v-col v-for="m in [{title:'دریافتی گزارش',key:'collected_irr',source:report},{title:'مانده پرداخت',key:'outstanding_irr',source:report},{title:'درآمد مرکز از دفتر',key:'center_revenue_irr',source:report},{title:'طلب مشاوران',key:'counselor_payable_irr',source:report},{title:'تسویه‌شده',key:'paid_settlements_irr',source:financeSummary},{title:'بازپرداخت کامل‌شده',key:'refunds_irr',source:financeSummary}]" :key="m.key" cols="12" sm="6" lg="4"><v-card class="pa-4"><div>{{ m.title }}</div><strong>{{ money(m.source ? m.source[m.key] : 0) }}</strong></v-card></v-col></v-row><v-alert type="info" variant="tonal" class="my-4">ظرفیت مشاور برابر ساعات کاری برنامه‌ریزی‌شده است و مرخصی یا تداخل اتاق را کم نمی‌کند؛ این درصد، ظرفیت دقیق قابل رزرو مرکز نیست.</v-alert><v-card v-if="report?.scheduled_capacity_minutes !== null && report?.scheduled_capacity_minutes !== undefined" class="pa-4 mb-4"><h3>ظرفیت برنامه‌ریزی‌شدهٔ مشاوران</h3><div>{{ Number(report.utilized_minutes||0).toLocaleString('fa-IR') }} دقیقه از {{ Number(report.scheduled_capacity_minutes||0).toLocaleString('fa-IR') }} دقیقه · نرخ ثبت‌شده {{ Number(report.capacity_utilization_percent||0).toLocaleString('fa-IR')}}٪</div></v-card><v-row><v-col cols="12" lg="6"><v-card class="pa-4"><h3>دریافتی به تفکیک خدمت</h3><v-list><v-list-item v-for="item in financeSummary.service_revenue||[]" :key="item.id" :title="item.title" :subtitle="money(item.revenue_irr)"/><v-list-item v-if="!financeSummary.service_revenue?.length" title="داده‌ای برای این بازه نیست."/></v-list></v-card></v-col><v-col cols="12" lg="6"><v-card class="pa-4"><h3>دریافتی به تفکیک مشاور</h3><v-list><v-list-item v-for="item in financeSummary.counselor_revenue||[]" :key="item.id" :title="item.name" :subtitle="money(item.revenue_irr)"/><v-list-item v-if="!financeSummary.counselor_revenue?.length" title="داده‌ای برای این بازه نیست."/></v-list></v-card></v-col></v-row><v-alert type="info" class="my-4">خلاصه‌ها از گزارش‌ها و دفتر backend می‌آیند. جدول پرداخت‌ها صفحه‌بندی‌شده است؛ CSV گزارش رزرو از خروجی واقعی backend دریافت می‌شود.</v-alert><v-card class="pa-4 my-4"><h3>مطابقت حساب‌ها</h3><div>اختلاف پرداخت: {{ reconciliation?.payment_mismatches?.length||0 }} · رویداد دفتر نامتوازن: {{ reconciliation?.unbalanced_ledger_events?.length||0 }}</div><div v-for="x in reconciliation?.payment_mismatches||[]" :key="x.id">نوبت {{ x.id }}: {{ money(x.paid_irr) }} / {{ money(x.verified_irr) }}</div></v-card><v-card class="mb-4"><h3 class="pa-4">پرداخت‌ها</h3><v-table><thead><tr><th>نوبت</th><th>مبلغ</th><th>روش</th><th>وضعیت</th><th>مرجع</th><th>زمان</th></tr></thead><tbody><tr v-for="p in rows" :key="p.id"><td>{{ p.booking_id }}</td><td>{{ money(p.amount_irr) }}</td><td>{{ p.payment_method||p.provider }}</td><td>{{ label(p.status) }}</td><td>{{ p.provider_reference||'—' }}</td><td>{{ dateTime(p.verified_at||p.created_at) }}</td></tr></tbody></v-table><div v-if="!rows.length&&!loading" class="pa-4">پرداختی یافت نشد.</div></v-card><v-card class="pa-4"><div class="d-flex justify-space-between"><h3>تسویه مشاوران</h3><v-btn v-if="auth.can('finance.manage')" @click="dialog='settlement'">ثبت تسویه</v-btn></div><div v-if="payable" class="my-3">مانده قابل پرداخت: {{ money(payable.payable_irr) }}</div><v-table><thead><tr><th>مشاور</th><th>مبلغ</th><th>مرجع</th><th>زمان</th></tr></thead><tbody><tr v-for="s in extra" :key="s.id"><td>{{ counselorName(s.counselor_id) }}</td><td>{{ money(s.amount_irr) }}</td><td>{{ s.reference }}</td><td>{{ dateTime(s.created_at) }}</td></tr></tbody></v-table></v-card></template>

    <template v-if="section==='refunds'"><v-alert type="info" class="mb-4">جریمهٔ پیشنهادی لغو طبق تنظیمات سرور محاسبه می‌شود (پیش‌فرض ۱۰٪). ثبت انتقال فقط پس از انجام واقعی بازپرداخت است.</v-alert><v-card><v-table><thead><tr><th>نوبت</th><th>وضعیت</th><th>پرداخت شده</th><th>جریمه</th><th>بازپرداخت</th><th>مرجع</th><th>اقدام</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{ r.booking_id }}</td><td>{{ label(r.status) }}</td><td>{{ money(r.base_amount_irr) }}</td><td>{{ money(r.penalty_irr) }}</td><td>{{ money(r.refund_amount_irr) }}</td><td>{{ r.transfer_reference||'—' }}</td><td><template v-if="auth.can('finance.manage')"><v-btn v-if="r.status==='requested'" size="small" :disabled="busy" @click="decideRefund(r,'approved')">تأیید</v-btn><v-btn v-if="r.status==='requested'" size="small" :disabled="busy" @click="decideRefund(r,'rejected')">رد</v-btn><v-btn v-if="r.status==='approved'" size="small" :disabled="busy" @click="transferRefund(r)">ثبت انتقال انجام شده</v-btn></template></td></tr></tbody></v-table><div v-if="!rows.length&&!loading" class="pa-6">درخواست لغوی یافت نشد.</div></v-card></template>

    <template v-if="section==='notifications'"><v-card><v-table><thead><tr><th>نوبت</th><th>کانال</th><th>رویداد</th><th>وضعیت</th><th>زمان</th></tr></thead><tbody><tr v-for="n in rows" :key="n.id"><td>{{ n.booking_id }}</td><td>{{ n.channel }}</td><td>{{ n.event }}</td><td>{{ label(n.status) }}</td><td>{{ dateTime(n.created_at) }}</td></tr></tbody></v-table><div v-if="!rows.length&&!loading" class="pa-6">لاگی یافت نشد.</div></v-card></template>
    <div v-if="['appointments','services','finance','refunds','notifications'].includes(section) && totalPages>1" class="d-flex align-center justify-center ga-3 mt-4"><v-btn :disabled="currentPage<=1" @click="currentPage--">قبلی</v-btn><span>صفحه {{ currentPage }} از {{ totalPages }}</span><v-btn :disabled="currentPage>=totalPages" @click="currentPage++">بعدی</v-btn></div>

    <v-dialog v-model="partialRefundOpen" max-width="520"><v-card class="pa-5" dir="rtl"><h3>درخواست بازپرداخت جزئی · نوبت #{{ selected?.id }}</h3><v-alert type="info" variant="tonal">مبلغ درخواستی نباید از ماندهٔ پرداخت‌نشدهٔ بازپرداخت بیشتر باشد؛ backend اعتبارسنجی می‌کند.</v-alert><v-text-field v-model.number="refundForm.amount_irr" type="number" min="1" :max="selected?.paid_irr" label="مبلغ (ریال)"/><v-textarea v-model="refundForm.reason" label="دلیل"/><v-btn color="primary" :loading="busy" :disabled="refundForm.amount_irr<=0||!refundForm.reason.trim()" @click="requestPartialRefund">ثبت درخواست</v-btn></v-card></v-dialog>
    <v-dialog :model-value="!!dialog" max-width="850" scrollable @update:model-value="v=>{if(!v)dialog=''}"><v-card class="pa-5" dir="rtl"><div class="d-flex justify-space-between align-center mb-4"><h3>{{ dialog==='detail'?'جزئیات نوبت':dialog==='new'?'ثبت نوبت':dialog==='service'?'خدمت رزرو':dialog==='client'?'سوابق مراجع':dialog==='newClient'?'مراجع جدید':dialog==='settlement'?'ثبت تسویه':'تغییر زمان نوبت' }}</h3><v-btn variant="text" @click="dialog=''">بستن</v-btn></div>
      <template v-if="dialog==='new'"><v-alert type="info" class="mb-3">زمان انتخابی باید از ظرفیت آزاد همان مشاور و خدمت باشد.</v-alert><v-text-field v-model="clientQ" label="جست‌وجوی مراجع با نام یا تلفن" @keyup.enter="findClients" /><v-btn size="small" class="mb-3" @click="findClients">جست‌وجو</v-btn><v-btn size="small" class="mb-3 mr-2" @click="dialog='newClient'">مراجع جدید</v-btn><v-select v-model="bookingForm.user_id" :items="clients" item-title="name" item-value="id" label="مراجع" /><v-row><v-col cols="12" md="6"><v-text-field v-if="!counselors.length" v-model.number="bookingForm.counselor_id" type="number" label="شناسه مشاور" @change="fetchSlots" /><v-select v-else v-model="bookingForm.counselor_id" :items="counselors" item-title="name" item-value="id" label="مشاور" @update:model-value="fetchSlots" /></v-col><v-col cols="12" md="6"><v-select v-model="bookingForm.service_id" :items="services.filter(s=>s.is_active)" item-title="title" item-value="id" label="خدمت" @update:model-value="fetchSlots" /></v-col><v-col cols="12" md="6"><v-text-field v-model="calDate" type="date" label="تاریخ (تهران)" @update:model-value="fetchSlots" /></v-col><v-col cols="12" md="6"><v-select v-model="bookingForm.starts_at" :items="availableSlots" :item-title="s=>dateTime(s.starts_at)" item-value="starts_at" label="ساعت آزاد" /></v-col><v-col cols="12" md="6"><v-select v-model="bookingForm.mode" :items="[{title:'حضوری',value:'in_person'},{title:'آنلاین',value:'online'}]" label="نوع جلسه" /></v-col><v-col v-if="bookingForm.mode==='in_person'" cols="12" md="6"><v-select v-model="bookingForm.room_id" :items="rooms.filter(r=>r.is_active)" item-title="name" item-value="id" label="اتاق (اختیاری؛ تداخل سمت سرور بررسی می‌شود)" clearable /></v-col><v-col cols="12" md="6"><v-select v-model="bookingForm.payment_option" :items="[{title:'بیعانه',value:'deposit'},{title:'کامل',value:'full'}]" label="نوع پرداخت" /></v-col><v-col cols="12" md="6"><v-text-field v-model="bookingForm.promo_code" label="کد تخفیف (اختیاری)" /></v-col></v-row><v-btn color="primary" :loading="busy" :disabled="!bookingForm.user_id||!bookingForm.starts_at" @click="createBooking">ثبت نوبت</v-btn></template>
      <template v-else-if="dialog==='detail'&&selected"><v-row><v-col cols="12" md="6">نوبت #{{ selected.id }} · {{ label(selected.status) }}<br>مراجع #{{ selected.user_id }} · {{ counselorName(selected.counselor_id) }}<br>{{ serviceName(selected.booking_service_id) }} · {{ selected.mode==='in_person'?'حضوری':'آنلاین' }}<br>{{ dateTime(selected.starts_at) }} تا {{ dateTime(selected.ends_at) }}</v-col><v-col cols="12" md="6">کل: {{ money(selected.total_irr) }}<br>دریافت: {{ money(selected.paid_irr) }}<br>تخفیف: {{ money(selected.discount_irr) }}<br>مانده: {{ money(selected.remaining_irr) }}<br>اتاق: {{ selected.room_name || selected.room_id || 'تعیین‌نشده' }}<br>مبلغ لازم برای تأیید: {{ money(selected.required_irr) }}</v-col></v-row><div class="d-flex flex-wrap ga-2 my-4"><v-btn v-if="['held','confirmed'].includes(selected.status)" :disabled="busy" @click="previewReschedule(selected)">تغییر زمان</v-btn><v-btn v-if="['held','confirmed'].includes(selected.status)&&!Number(selected.paid_irr)" color="error" :disabled="busy" @click="cancelBooking">لغو بدون پرداخت</v-btn><v-btn v-if="selected.status==='confirmed'" color="primary" variant="tonal" :disabled="busy" @click="checkInSelected">ثبت ورود</v-btn><v-btn v-if="selected.status==='checked_in'" color="info" variant="tonal" :disabled="busy" @click="setSessionStatus('in_progress')">شروع جلسه</v-btn><v-btn v-if="['confirmed','checked_in','in_progress'].includes(selected.status)" color="success" variant="tonal" :disabled="busy" @click="setSessionStatus('completed')">ثبت برگزاری</v-btn><v-btn v-if="selected.status==='confirmed'" color="error" variant="outlined" :disabled="busy" @click="setSessionStatus('no_show')">ثبت عدم حضور</v-btn><v-btn v-if="auth.can('finance.manage')&&Number(selected.paid_irr)>0" color="warning" variant="outlined" :disabled="busy" @click="partialRefundOpen=true">درخواست بازپرداخت جزئی</v-btn></div><v-row v-if="['held','confirmed','checked_in'].includes(selected.status)" class="mb-3"><v-col cols="12" md="6"><v-select v-model="bookingForm.room_id" :items="rooms.filter(r=>r.is_active)" item-title="name" item-value="id" label="اتاق" clearable/></v-col><v-col cols="12" md="6"><v-btn :disabled="busy" @click="assignSelectedRoom">ذخیرهٔ تخصیص اتاق</v-btn></v-col></v-row><template v-if="selected.mode==='in_person'&&['held','confirmed'].includes(selected.status)"><h4>ثبت پرداخت حضوری</h4><v-row><v-col cols="12" md="4"><v-text-field v-model.number="paymentForm.amount_irr" type="number" label="مبلغ (ریال)" /></v-col><v-col cols="12" md="3"><v-select v-model="paymentForm.payment_method" :items="['cash','pos']" label="روش" /></v-col><v-col cols="12" md="5"><v-text-field v-model="paymentForm.reference" label="شماره رسید / مرجع" /></v-col></v-row><v-btn :disabled="busy||paymentForm.amount_irr<=0" @click="recordPayment">ثبت پرداخت واقعی</v-btn></template><template v-if="auth.can('finance.view')"><h4 class="mt-5">پرداخت‌ها و بازپرداخت‌ها</h4><div v-for="p in payments" :key="p.id">{{ money(p.amount_irr) }} · {{ label(p.status) }} · {{ p.provider_reference||p.payment_method }}</div><div v-for="r in refunds" :key="r.id">بازپرداخت {{ money(r.refund_amount_irr) }} · {{ label(r.status) }}</div><div v-if="!payments.length&&!refunds.length" class="text-medium-emphasis">موردی یافت نشد.</div></template><template v-if="auth.can('notes.manage')"><h4 class="mt-5">یادداشت‌ها</h4><div v-for="n in notes" :key="n.id" class="py-2">{{ n.body }} <v-chip size="x-small">{{ n.visible_to_client?'قابل مشاهده برای مراجع':'خصوصی' }}</v-chip></div><v-textarea v-model="noteForm.body" label="متن یادداشت" /><v-switch v-model="noteForm.visible_to_client" label="قابل مشاهده برای مراجع" /><v-btn :disabled="busy||!noteForm.body.trim()" @click="addNote">ثبت یادداشت</v-btn></template></template>
      <template v-else-if="dialog==='reschedule'"><v-text-field v-model="calDate" type="date" label="تاریخ جدید" @update:model-value="fetchSlots" /><v-select :items="availableSlots" :item-title="s=>dateTime(s.starts_at)" item-value="starts_at" label="ساعت آزاد" @update:model-value="v=>bookingForm.starts_at=v" /><v-btn :disabled="busy||!bookingForm.starts_at" @click="reschedule(bookingForm.starts_at)">ثبت تغییر زمان</v-btn></template>
      <template v-else-if="dialog==='service'"><v-text-field v-model="serviceForm.title" label="نام خدمت" /><v-row><v-col cols="12" md="4"><v-text-field v-model.number="serviceForm.duration_minutes" type="number" label="مدت (دقیقه)" /></v-col><v-col cols="12" md="4"><v-text-field v-model.number="serviceForm.price_irr" type="number" label="قیمت (ریال)" /></v-col><v-col cols="12" md="4"><v-text-field v-model.number="serviceForm.deposit_irr" type="number" label="بیعانه (ریال)" /></v-col></v-row><v-switch v-model="serviceForm.is_active" label="فعال" /><v-btn :disabled="busy||!serviceForm.title||serviceForm.price_irr<1||serviceForm.deposit_irr>serviceForm.price_irr" @click="saveService">ذخیره</v-btn></template>
      <template v-else-if="dialog==='newClient'"><v-text-field v-model="clientForm.name" label="نام" /><v-text-field v-model="clientForm.email" type="email" label="ایمیل" /><v-text-field v-model="clientForm.phone" label="تلفن" /><v-btn :disabled="busy||!clientForm.name||!clientForm.email||!clientForm.phone" @click="createClient">ایجاد حساب مراجع</v-btn></template>
      <template v-else-if="dialog==='client'"><div>{{ selectedClient?.name }} · {{ selectedClient?.phone }}</div><h4 class="my-3">سوابق نوبت</h4><v-list><v-list-item v-for="b in bookings" :key="b.id" :title="dateTime(b.starts_at)" :subtitle="`${serviceName(b.booking_service_id)} · ${label(b.status)}`" @click="detail(b)" /></v-list><div v-if="!bookings.length" class="text-medium-emphasis">نوبتی یافت نشد.</div></template>
      <template v-else-if="dialog==='settlement'"><v-text-field v-if="!counselors.length" v-model.number="settlement.counselor_id" type="number" label="شناسه مشاور" /><v-select v-else v-model="settlement.counselor_id" :items="counselors" item-title="name" item-value="id" label="مشاور" /><v-text-field v-model.number="settlement.amount_irr" type="number" label="مبلغ (ریال)" /><v-text-field v-model="settlement.reference" label="مرجع انتقال انجام شده" /><v-textarea v-model="settlement.note" label="توضیح" /><v-btn :disabled="busy||!settlement.counselor_id||settlement.amount_irr<=0||!settlement.reference" @click="settle">ثبت تسویه انجام شده</v-btn></template>
    </v-card></v-dialog>
  </div>
</template>
